package webhook

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"log/slog"
	"math"
	"strconv"
	"time"
)

const MaxSkewSeconds = 300

type DedupeStore interface {
	ClaimOnce(tenantID, deliveryID string, ttl time.Duration) (bool, error)
}

func SignPayload(secret []byte, deliveryID string, ts int64, body []byte) string {
	mac := hmac.New(sha256.New, secret)
	fmt.Fprintf(mac, "%d.%s.", ts, deliveryID)
	mac.Write(body)
	return "v1=" + hex.EncodeToString(mac.Sum(nil))
}

func VerifyDelivery(
	secret []byte,
	tenantID, deliveryID, tsHeader, sigHeader string,
	body []byte,
	now time.Time,
	store DedupeStore,
	log *slog.Logger,
) error {
	ts, err := strconv.ParseInt(tsHeader, 10, 64)
	if err != nil || deliveryID == "" {
		log.Warn("webhook_verify_rejected", "tenant_id", tenantID, "reason", "malformed_headers")
		return errors.New("invalid webhook metadata")
	}
	if math.Abs(float64(now.Unix()-ts)) > MaxSkewSeconds {
		log.Warn("webhook_verify_rejected", "tenant_id", tenantID, "reason", "timestamp_out_of_window")
		return errors.New("webhook timestamp outside replay window")
	}
	expected := SignPayload(secret, deliveryID, ts, body)
	if !hmac.Equal([]byte(expected), []byte(sigHeader)) {
		log.Warn("webhook_verify_rejected", "tenant_id", tenantID, "reason", "bad_signature")
		return errors.New("signature mismatch")
	}
	fresh, err := store.ClaimOnce(tenantID, deliveryID, 2*MaxSkewSeconds*time.Second)
	if err != nil || !fresh {
		log.Warn("webhook_verify_rejected", "tenant_id", tenantID, "reason", "duplicate_delivery")
		return errors.New("replayed delivery id")
	}
	return nil
}
