import { verifyAuthenticationResponse, AuthenticationResponseJSON } from "@simplewebauthn/server";
import { createHash } from "node:crypto";

interface PendingStepUp {
  challenge: string;
  userId: string;
  actionDigest: string;
  expiresAtMs: number;
}

interface StepUpDeps {
  consumeChallenge(txId: string): Promise<PendingStepUp | null>;
  loadPasskey(userId: string, credId: string): Promise<{ publicKey: Uint8Array; counter: number } | null>;
  updateCounter(credId: string, newCounter: number): Promise<void>;
  audit(event: string, meta: Record<string, unknown>): void;
}

export function hashTransferIntent(accountTo: string, amountCents: bigint, currency: string): string {
  return createHash("sha256").update(`${accountTo}|${amountCents.toString()}|${currency}`).digest("hex");
}

export async function verifyTransferStepUp(
  deps: StepUpDeps,
  txId: string,
  sessionUserId: string,
  intentDigest: string,
  assertion: AuthenticationResponseJSON,
  expectedOrigin: string,
  expectedRPID: string,
): Promise<void> {
  const pending = await deps.consumeChallenge(txId);
  if (!pending || Date.now() > pending.expiresAtMs) {
    deps.audit("stepup_rejected", { userId: sessionUserId, reason: "expired_or_missing_challenge" });
    throw new Error("Invalid step-up challenge");
  }
  if (pending.userId !== sessionUserId || pending.actionDigest !== intentDigest) {
    deps.audit("stepup_rejected", { userId: sessionUserId, reason: "intent_or_principal_mismatch" });
    throw new Error("Step-up context mismatch");
  }
  const passkey = await deps.loadPasskey(sessionUserId, assertion.id);
  if (!passkey) {
    deps.audit("stepup_rejected", { userId: sessionUserId, reason: "unknown_credential" });
    throw new Error("Unregistered passkey");
  }
  const result = await verifyAuthenticationResponse({
    response: assertion,
    expectedChallenge: pending.challenge,
    expectedOrigin,
    expectedRPID,
    requireUserVerification: true,
    credential: { id: assertion.id, publicKey: passkey.publicKey, counter: passkey.counter },
  });
  if (!result.verified) {
    deps.audit("stepup_rejected", { userId: sessionUserId, reason: "assertion_failed" });
    throw new Error("WebAuthn assertion failed");
  }
  if (passkey.counter > 0 && result.authenticationInfo.newCounter <= passkey.counter) {
    deps.audit("stepup_rejected", { userId: sessionUserId, reason: "sign_count_regression" });
    throw new Error("Cloned authenticator suspected");
  }
  await deps.updateCounter(assertion.id, result.authenticationInfo.newCounter);
  deps.audit("stepup_verified", { userId: sessionUserId, credId: assertion.id });
}
