package safedial

import (
	"errors"
	"log/slog"
	"net"
	"net/http"
	"net/netip"
	"syscall"
	"time"
)

var cgnatPrefix = netip.MustParsePrefix("100.64.0.0/10")

func isPublicUnicast(rawIP string) bool {
	addr, err := netip.ParseAddr(rawIP)
	if err != nil {
		return false
	}
	addr = addr.Unmap()
	if addr.IsLoopback() || addr.IsPrivate() || addr.IsLinkLocalUnicast() ||
		addr.IsLinkLocalMulticast() || addr.IsMulticast() || addr.IsUnspecified() ||
		cgnatPrefix.Contains(addr) {
		return false
	}
	return addr.IsGlobalUnicast()
}

func NewTenantWebhookClient(tenantID string, log *slog.Logger) *http.Client {
	dialer := &net.Dialer{
		Timeout:   5 * time.Second,
		KeepAlive: 15 * time.Second,
		Control: func(network, address string, _ syscall.RawConn) error {
			host, port, err := net.SplitHostPort(address)
			if err != nil || (port != "443" && port != "8443") {
				log.Warn("webhook_egress_blocked", "tenant_id", tenantID, "addr", address, "reason", "disallowed_port")
				return errors.New("webhook destination port not permitted")
			}
			if !isPublicUnicast(host) {
				log.Warn("webhook_egress_blocked", "tenant_id", tenantID, "ip", host, "reason", "non_public_ip")
				return errors.New("webhook destination IP blocked")
			}
			return nil
		},
	}

	transport := &http.Transport{
		DialContext:           dialer.DialContext,
		ForceAttemptHTTP2:     true,
		TLSHandshakeTimeout:   5 * time.Second,
		ResponseHeaderTimeout: 10 * time.Second,
		DisableKeepAlives:     true,
	}

	return &http.Client{
		Transport: transport,
		Timeout:   15 * time.Second,
		CheckRedirect: func(*http.Request, []*http.Request) error {
			return http.ErrUseLastResponse
		},
	}
}
