```ts
export interface WidgetRpcMessage {
  channelNonce: string;
  action: "resize" | "notify";
  heightPx?: number;
  text?: string;
}

export function mountSandboxedWidget(
  container: HTMLElement,
  widgetHtmlUrl: string,
  onTelemetryDrop: (reason: string) => void,
  onSafeAction: (msg: WidgetRpcMessage) => void,
): () => void {
  const parsed = new URL(widgetHtmlUrl);
  if (parsed.protocol !== "https:") {
    throw new Error("Widget URL must use HTTPS");
  }

  const bytes = new Uint8Array(16);
  crypto.getRandomValues(bytes);
  const channelNonce = Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("");

  const frame = document.createElement("iframe");
  frame.setAttribute("sandbox", "allow-scripts");
  frame.setAttribute("referrerpolicy", "no-referrer");
  frame.setAttribute("allow", "none");
  frame.src = `${parsed.toString()}#nonce=${channelNonce}`;
  container.appendChild(frame);

  const onMessage = (event: MessageEvent<unknown>): void => {
    if (event.source !== frame.contentWindow) {
      return;
    }
    if (event.origin !== "null") {
      onTelemetryDrop("unexpected_non_opaque_origin");
      return;
    }
    if (typeof event.data !== "object" || event.data === null) {
      onTelemetryDrop("malformed_payload");
      return;
    }
    const candidate = event.data as Partial<WidgetRpcMessage>;
    if (candidate.channelNonce !== channelNonce) {
      onTelemetryDrop("channel_nonce_mismatch");
      return;
    }
    if (candidate.action === "resize" && typeof candidate.heightPx === "number" &&
        candidate.heightPx >= 40 && candidate.heightPx <= 1200) {
      onSafeAction({ channelNonce, action: "resize", heightPx: candidate.heightPx });
      return;
    }
    if (candidate.action === "notify" && typeof candidate.text === "string" && candidate.text.length <= 140) {
      onSafeAction({ channelNonce, action: "notify", text: candidate.text });
      return;
    }
    onTelemetryDrop("schema_validation_failed");
  };

  window.addEventListener("message", onMessage);
  return () => {
    window.removeEventListener("message", onMessage);
    frame.remove();
  };
}
```

