import { IncomingMessage, ServerResponse } from "node:http";
import { timingSafeEqual } from "node:crypto";

const ALLOWED_HOSTS = new Set(["127.0.0.1:3001", "localhost:3001"]);

function safeTokenMatch(headerVal: string | undefined, expectedToken: string): boolean {
  if (!headerVal || !headerVal.startsWith("Bearer ")) return false;
  const provided = Buffer.from(headerVal.slice(7), "utf8");
  const expected = Buffer.from(expectedToken, "utf8");
  if (provided.length !== expected.length) return false;
  return timingSafeEqual(provided, expected);
}

export function guardLocalMcpRequest(
  req: IncomingMessage,
  res: ServerResponse,
  sessionToken: string,
  auditDeny: (reason: string, meta: Record<string, string | undefined>) => void,
): boolean {
  const remoteIp = req.socket.remoteAddress;
  if (remoteIp !== "127.0.0.1" && remoteIp !== "::1") {
    auditDeny("non_loopback_peer", { remoteIp });
    res.writeHead(403, { "Content-Type": "application/json" }).end('{"error":"forbidden"}');
    return false;
  }

  const host = (req.headers.host ?? "").toLowerCase();
  if (!ALLOWED_HOSTS.has(host)) {
    auditDeny("dns_rebinding_host_mismatch", { host });
    res.writeHead(403, { "Content-Type": "application/json" }).end('{"error":"invalid_host"}');
    return false;
  }

  const origin = req.headers.origin;
  const fetchSite = req.headers["sec-fetch-site"];
  if (origin !== undefined || (fetchSite !== undefined && fetchSite !== "none")) {
    auditDeny("browser_origin_blocked", { origin, fetchSite: String(fetchSite) });
    res.writeHead(403, { "Content-Type": "application/json" }).end('{"error":"browser_requests_denied"}');
    return false;
  }

  if (!safeTokenMatch(req.headers.authorization, sessionToken)) {
    auditDeny("missing_or_invalid_token", { remoteIp });
    res.writeHead(401, { "Content-Type": "application/json" }).end('{"error":"unauthorized"}');
    return false;
  }

  return true;
}
