```ts
import { IncomingMessage, ServerResponse } from "node:http";

const SAFE_METHODS = new Set(["GET", "HEAD", "OPTIONS"]);

export interface SessionRecord {
  userId: string;
  tenantId: string;
  downstreamAccessToken: string;
  expiresAtMs: number;
}

export function parseHostSessionCookie(cookieHeader: string | undefined): string | null {
  if (!cookieHeader) return null;
  for (const part of cookieHeader.split(";")) {
    const [rawName, ...rest] = part.trim().split("=");
    if (rawName === "__Host-sess" && rest.length > 0) {
      return rest.join("=");
    }
  }
  return null;
}

export async function bffProxyGuard(
  req: IncomingMessage,
  res: ServerResponse,
  expectedOrigin: string,
  lookupSession: (sid: string) => Promise<SessionRecord | null>,
  onDenyMetric: (reason: string) => void,
): Promise<SessionRecord | null> {
  const method = (req.method ?? "GET").toUpperCase();
  if (!SAFE_METHODS.has(method)) {
    const fetchSite = req.headers["sec-fetch-site"];
    const origin = req.headers.origin;
    const csrfHeader = req.headers["x-bff-csrf"];
    if (fetchSite !== "same-origin" || origin !== expectedOrigin || csrfHeader !== "1") {
      onDenyMetric("csrf_boundary_violation");
      res.writeHead(403, { "Content-Type": "application/json" }).end('{"error":"csrf_rejected"}');
      return null;
    }
  }

  const sid = parseHostSessionCookie(req.headers.cookie);
  if (!sid) {
    onDenyMetric("missing_host_cookie");
    res.writeHead(401, { "Content-Type": "application/json" }).end('{"error":"unauthenticated"}');
    return null;
  }

  const sess = await lookupSession(sid);
  if (!sess || Date.now() >= sess.expiresAtMs) {
    onDenyMetric("expired_or_unknown_session");
    res.writeHead(401, {
      "Content-Type": "application/json",
      "Set-Cookie": "__Host-sess=; Path=/; Secure; HttpOnly; SameSite=Strict; Max-Age=0",
    }).end('{"error":"session_expired"}');
    return null;
  }
  return sess;
}
```

