package passhash

import (
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/base64"
	"errors"
	"fmt"
	"strings"

	"golang.org/x/crypto/argon2"
)

const (
	ArgonTime    uint32 = 3
	ArgonMemory  uint32 = 64 * 1024
	ArgonThreads uint8  = 4
	KeyLen       uint32 = 32
	SaltLen      int    = 16
)

func prePepper(pepperKey []byte, password string) []byte {
	mac := hmac.New(sha256.New, pepperKey)
	mac.Write([]byte(password))
	return mac.Sum(nil)
}

func HashPassword(pepperKey []byte, password string) (string, error) {
	if len(pepperKey) < 32 || len(password) < 12 {
		return "", errors.New("invalid pepper length or password policy violation")
	}
	salt := make([]byte, SaltLen)
	if _, err := rand.Read(salt); err != nil {
		return "", err
	}
	peppered := prePepper(pepperKey, password)
	derived := argon2.IDKey(peppered, salt, ArgonTime, ArgonMemory, ArgonThreads, KeyLen)
	return fmt.Sprintf(
		"$argon2id$v=19$m=%d,t=%d,p=%d$%s$%s",
		ArgonMemory, ArgonTime, ArgonThreads,
		base64.RawStdEncoding.EncodeToString(salt),
		base64.RawStdEncoding.EncodeToString(derived),
	), nil
}

func VerifyPassword(pepperKey []byte, password, encoded string, onFailure func()) (bool, error) {
	parts := strings.Split(encoded, "$")
	if len(parts) != 6 || parts[1] != "argon2id" {
		onFailure()
		return false, errors.New("unsupported hash encoding")
	}
	var mem, iter uint32
	var par uint8
	if _, err := fmt.Sscanf(parts[3], "m=%d,t=%d,p=%d", &mem, &iter, &par); err != nil {
		onFailure()
		return false, err
	}
	salt, err := base64.RawStdEncoding.DecodeString(parts[4])
	if err != nil {
		onFailure()
		return false, err
	}
	expected, err := base64.RawStdEncoding.DecodeString(parts[5])
	if err != nil {
		onFailure()
		return false, err
	}
	peppered := prePepper(pepperKey, password)
	candidate := argon2.IDKey(peppered, salt, iter, mem, par, uint32(len(expected)))
	if subtle.ConstantTimeCompare(candidate, expected) != 1 {
		onFailure()
		return false, nil
	}
	return true, nil
}
