use sha2::{Digest, Sha256};

#[derive(Debug, Clone)]
pub struct UpdateManifest {
    pub sequence: u64,
    pub expires_unix: u64,
    pub artifact_sha256: [u8; 32],
}

#[derive(Debug, PartialEq, Eq)]
pub enum UpdateVerifyError {
    SignatureInvalid,
    RollbackDetected,
    ManifestExpired,
    ArtifactDigestMismatch,
}

impl UpdateManifest {
    pub fn canonical_bytes(&self) -> [u8; 56] {
        let mut buf = [0u8; 56];
        buf[0..8].copy_from_slice(b"UPD-V1��");
        buf[8..16].copy_from_slice(&self.sequence.to_be_bytes());
        buf[16..24].copy_from_slice(&self.expires_unix.to_be_bytes());
        buf[24..56].copy_from_slice(&self.artifact_sha256);
        buf
    }
}

pub fn verify_signed_update(
    pubkey: &VerifyingKey,
    manifest: &UpdateManifest,
    sig_bytes: &[u8; 64],
    installed_sequence: u64,
    now_unix: u64,
    artifact_bytes: &[u8],
    on_reject: &dyn Fn(&str),
) -> Result<(), UpdateVerifyError> {
    let sig = Signature::from_bytes(sig_bytes);
    let msg = manifest.canonical_bytes();
    if pubkey.verify_strict(&msg, &sig).is_err() {
        on_reject("signature_invalid");
        return Err(UpdateVerifyError::SignatureInvalid);
    }
    if manifest.sequence <= installed_sequence {
        on_reject("rollback_sequence_blocked");
        return Err(UpdateVerifyError::RollbackDetected);
    }
    if now_unix >= manifest.expires_unix {
        on_reject("manifest_expired");
        return Err(UpdateVerifyError::ManifestExpired);
    }
    let actual_hash: [u8; 32] = Sha256::digest(artifact_bytes).into();
    if actual_hash != manifest.artifact_sha256 {
        on_reject("artifact_digest_mismatch");
        return Err(UpdateVerifyError::ArtifactDigestMismatch);
    }
    Ok(())
}
