import hmac
import logging
from dataclasses import dataclass
from typing import Any, Callable, Dict

log = logging.getLogger("ai.tool_gate")


@dataclass(frozen=True)
class ToolSpec:
    name: str
    mutating: bool
    max_calls_per_session: int
    handler: Callable[[str, Dict[str, Any]], Any]


class ToolPolicyGate:
    def __init__(self, registry: Dict[str, ToolSpec], approval_secret: bytes) -> None:
        self._registry = registry
        self._secret = approval_secret
        self._counts: Dict[tuple[str, str], int] = {}

    def verify_human_approval(self, session_id: str, tool_name: str, token: str | None) -> bool:
        if not token:
            return False
        expected = hmac.new(
            self._secret,
            f"{session_id}:{tool_name}".encode("utf-8"),
            "sha256",
        ).hexdigest()
        return hmac.compare_digest(expected, token)

    def dispatch(
        self,
        session_id: str,
        verified_tenant_id: str,
        tool_name: str,
        args: Dict[str, Any],
        human_approval_token: str | None = None,
    ) -> Any:
        spec = self._registry.get(tool_name)
        if spec is None:
            log.warning("tool_gate_denied session=%s reason=unknown_tool tool=%s", session_id, tool_name)
            raise PermissionError(f"Unregistered tool: {tool_name}")

        used = self._counts.get((session_id, tool_name), 0)
        if used >= spec.max_calls_per_session:
            log.warning("tool_gate_denied session=%s reason=budget_exceeded tool=%s", session_id, tool_name)
            raise PermissionError("Session tool budget exceeded")

        if spec.mutating and not self.verify_human_approval(session_id, tool_name, human_approval_token):
            log.warning("tool_gate_denied session=%s reason=missing_human_approval tool=%s", session_id, tool_name)
            raise PermissionError("Mutating tool requires explicit human approval")

        self._counts[(session_id, tool_name)] = used + 1
        return spec.handler(verified_tenant_id, args)
