#[derive(Debug, Clone)]
pub struct VerifiedOidcClaims {
    pub sub: String,
    pub tenant_id: String,
    pub acr: String,
    pub amr: Vec<String>,
    pub auth_time: u64,
    pub exp: u64,
}

#[derive(Debug, PartialEq, Eq)]
pub enum StepUpDenied {
    TokenExpired,
    FutureAuthTime,
    InsufficientAcr,
    MissingHardwareAmr,
    StaleAuthentication,
}

const MAX_STEPUP_AGE_SECS: u64 = 300;
const REQUIRED_ACR: &str = "urn:acme:acr:webauthn";

pub fn enforce_ownership_transfer_stepup(
    claims: &VerifiedOidcClaims,
    now_unix: u64,
    on_deny_metric: &dyn Fn(&str, &str),
) -> Result<(), StepUpDenied> {
    if now_unix >= claims.exp {
        on_deny_metric(&claims.tenant_id, "token_expired");
        return Err(StepUpDenied::TokenExpired);
    }
    if claims.auth_time > now_unix + 15 {
        on_deny_metric(&claims.tenant_id, "clock_skew_auth_time");
        return Err(StepUpDenied::FutureAuthTime);
    }
    if claims.acr != REQUIRED_ACR {
        on_deny_metric(&claims.tenant_id, "insufficient_acr");
        return Err(StepUpDenied::InsufficientAcr);
    }
    if !claims.amr.iter().any(|m| m == "hwk" || m == "user-presence") {
        on_deny_metric(&claims.tenant_id, "missing_hwk_amr");
        return Err(StepUpDenied::MissingHardwareAmr);
    }
    if now_unix.saturating_sub(claims.auth_time) > MAX_STEPUP_AGE_SECS {
        on_deny_metric(&claims.tenant_id, "stale_auth_time");
        return Err(StepUpDenied::StaleAuthentication);
    }
    Ok(())
}
