CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE IF NOT EXISTS security_audit_ledger (
    seq_id BIGSERIAL PRIMARY KEY,
    tenant_id UUID NOT NULL,
    actor_id TEXT NOT NULL,
    action_name TEXT NOT NULL,
    recorded_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    prev_hash BYTEA NOT NULL,
    entry_hash BYTEA NOT NULL
);

CREATE OR REPLACE FUNCTION seal_audit_ledger_row() RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
    last_digest BYTEA;
BEGIN
    LOCK TABLE security_audit_ledger IN EXCLUSIVE MODE;
    SELECT entry_hash INTO last_digest
      FROM security_audit_ledger
     ORDER BY seq_id DESC
     LIMIT 1;

    NEW.prev_hash := COALESCE(last_digest, decode(repeat('00', 32), 'hex'));
    NEW.entry_hash := digest(
        encode(NEW.prev_hash, 'hex') || '|' ||
        NEW.tenant_id::text || '|' ||
        NEW.actor_id || '|' ||
        NEW.action_name || '|' ||
        NEW.recorded_at::text,
        'sha256'
    );
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION block_audit_ledger_mutation() RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION 'immutable_audit_ledger_violation op=% role=%', TG_OP, session_user
        USING ERRCODE = '42501';
END;
$$;

CREATE TRIGGER trg_seal_audit_ledger
    BEFORE INSERT ON security_audit_ledger
    FOR EACH ROW EXECUTE FUNCTION seal_audit_ledger_row();

CREATE TRIGGER trg_forbid_row_mutation
    BEFORE UPDATE OR DELETE ON security_audit_ledger
    FOR EACH ROW EXECUTE FUNCTION block_audit_ledger_mutation();

CREATE TRIGGER trg_forbid_truncate
    BEFORE TRUNCATE ON security_audit_ledger
    FOR EACH STATEMENT EXECUTE FUNCTION block_audit_ledger_mutation();

