package mtlsguard

import (
	"crypto/tls"
	"crypto/x509"
	"errors"
	"log/slog"
)

func NewHardenedMTLSConfig(
	serverCert tls.Certificate,
	internalCAPEM []byte,
	allowedSPIFFEURIs map[string]struct{},
	log *slog.Logger,
) (*tls.Config, error) {
	caPool := x509.NewCertPool()
	if !caPool.AppendCertsFromPEM(internalCAPEM) {
		return nil, errors.New("failed to parse internal mTLS CA bundle")
	}

	return &tls.Config{
		Certificates: []tls.Certificate{serverCert},
		ClientAuth:   tls.RequireAndVerifyClientCert,
		ClientCAs:    caPool,
		MinVersion:   tls.VersionTLS13,
		VerifyConnection: func(cs tls.ConnectionState) error {
			if len(cs.PeerCertificates) == 0 {
				log.Warn("mtls_peer_rejected", "reason", "missing_leaf_cert")
				return errors.New("missing peer leaf certificate")
			}
			leaf := cs.PeerCertificates[0]
			for _, uri := range leaf.URIs {
				if _, ok := allowedSPIFFEURIs[uri.String()]; ok {
					return nil
				}
			}
			log.Warn("mtls_peer_rejected", "reason", "unapproved_spiffe_san", "subject", leaf.Subject.String())
			return errors.New("peer SPIFFE URI not authorized")
		},
	}, nil
}
