use std::fs::{self, File};
use std::io::{self, Read};
use std::path::{Component, Path, PathBuf};
use zip::ZipArchive;

const MAX_ENTRIES: usize = 128;
const MAX_TOTAL_BYTES: u64 = 64 * 1024 * 1024;
const S_IFMT: u32 = 0o170000;
const S_IFLNK: u32 = 0o120000;

#[derive(Debug)]
pub enum UnpackError {
    TooManyEntries,
    UnsafeEntryPath,
    SymlinkForbidden,
    QuotaExceeded,
    Io(io::Error),
}

fn safe_join_normal_only(dest_root: &Path, entry_name: &str) -> Result<PathBuf, UnpackError> {
    let rel = Path::new(entry_name);
    let mut clean = dest_root.to_path_buf();
    let mut depth = 0usize;
    for comp in rel.components() {
        match comp {
            Component::Normal(part) => {
                clean.push(part);
                depth += 1;
            }
            _ => return Err(UnpackError::UnsafeEntryPath),
        }
    }
    if depth == 0 {
        return Err(UnpackError::UnsafeEntryPath);
    }
    Ok(clean)
}

pub fn unpack_tenant_zip<R: Read + io::Seek>(
    reader: R,
    dest_root: &Path,
    on_reject: &dyn Fn(&str),
) -> Result<u64, UnpackError> {
    let mut archive = ZipArchive::new(reader).map_err(|e| UnpackError::Io(e.into()))?;
    if archive.len() > MAX_ENTRIES {
        on_reject("entry_count_exceeded");
        return Err(UnpackError::TooManyEntries);
    }

    let mut total_written: u64 = 0;
    for idx in 0..archive.len() {
        let entry = archive.by_index(idx).map_err(|e| UnpackError::Io(e.into()))?;
        if let Some(mode) = entry.unix_mode() {
            if (mode & S_IFMT) == S_IFLNK {
                on_reject("symlink_entry_blocked");
                return Err(UnpackError::SymlinkForbidden);
            }
        }
        if entry.is_dir() {
            continue;
        }
        let out_path = safe_join_normal_only(dest_root, entry.name()).map_err(|e| {
            on_reject("path_traversal_blocked");
            e
        })?;
        if let Some(parent) = out_path.parent() {
            fs::create_dir_all(parent).map_err(UnpackError::Io)?;
        }

        let remaining = MAX_TOTAL_BYTES.saturating_sub(total_written);
        let mut bounded = entry.take(remaining + 1);
        let mut out_file = File::create(&out_path).map_err(UnpackError::Io)?;
        let copied = io::copy(&mut bounded, &mut out_file).map_err(UnpackError::Io)?;
        total_written = total_written.saturating_add(copied);
        if total_written > MAX_TOTAL_BYTES {
            let _ = fs::remove_file(&out_path);
            on_reject("decompression_quota_exceeded");
            return Err(UnpackError::QuotaExceeded);
        }
    }
    Ok(total_written)
}
